  1→import { useState, useCallback, useEffect } from 'react';
  2→import { ThemeProvider } from './contexts/ThemeContext';
  3→import { useTheme } from './hooks/useTheme';
  4→import { LanguageProvider } from './contexts/LanguageContext';
  5→import { useTranslation } from './hooks/useTranslation';
  6→import { AgentProvider } from './contexts/AgentContext';
  7→import { ConfigProvider } from './contexts/ConfigContext';
  8→import { FileUpload } from './components/FileUpload';
  9→import { QueryEditor } from './components/QueryEditor';
 10→import { ResultsTable } from './components/ResultsTable';
 11→import { ResultMarkdown } from './components/ResultMarkdown';
 12→import { Sidebar } from './components/Sidebar';
 13→import { ErrorMessage } from './components/ErrorMessage';
 14→import { AgentPanel } from './components/AgentPanel';
 15→import type { TableInfo, QueryResult } from './types';
 16→import './App.css';
 17→
 18→function findDuplicateFileNames(files: File[]): string[] {
 19→  const seen = new Set<string>();
 20→  const duplicates = new Set<string>();
 21→  for (const file of files) {
 22→    if (seen.has(file.name)) {
 23→      duplicates.add(file.name);
 24→    }
 25→    seen.add(file.name);
 26→  }
 27→  return Array.from(duplicates);
 28→}
 29→
 30→function AppContent({ tables, refreshTables }: { tables: TableInfo[]; refreshTables: () => Promise<void> }) {
 31→  const { theme, toggleTheme } = useTheme();
 32→  const { language, setLanguage, t } = useTranslation();
 33→  const [queryResult, setQueryResult] = useState<QueryResult | null>(null);
 34→  const [error, setError] = useState<string | { key: string; params: Record<string, string> } | null>(null);
 35→  const [editorQuery, setEditorQuery] = useState<string | undefined>(
 36→    () => tables.length > 0 ? `SELECT * FROM "${tables[0].name}" LIMIT 100` : undefined
 37→  );
 38→  const [sidebarCollapsed, setSidebarCollapsed] = useState(() => window.innerWidth < 768);
 39→  const [agentOpen, setAgentOpen] = useState(true);
 40→
 41→  useEffect(() => {
 42→    document.title = t('appTitle');
 43→  }, [t]);
 44→
 45→  useEffect(() => {
 46→    if (tables.length === 0) {
 47→      setQueryResult(null);
 48→      setError(null);
 49→      setEditorQuery(undefined);
 50→    }
 51→  }, [tables]);
 52→
 53→  const errorMessage = error
 54→    ? (typeof error === 'string' ? error : t(error.key, error.params))
 55→    : null;
 56→
 57→  const handleAgentToggle = () => {
 58→    setAgentOpen((prev) => !prev);
 59→  };
 60→
 61→  const handleLoadSample = useCallback(async () => {
 62→    setError(null);
 63→    try {
 64→      const response = await fetch('/api/upload/sample', { method: 'POST' });
 65→      if (!response.ok) throw new Error('Failed to load sample dataset');
 66→      await refreshTables();
 67→      setEditorQuery('SELECT * FROM "titanic" LIMIT 100');
 68→    } catch (e) {
 69→      setError(e instanceof Error ? e.message : 'Failed to load sample dataset');
 70→    }
 71→  }, [refreshTables]);
 72→
 73→  const handleFileUpload = useCallback(
 74→    async (files: File[]) => {
 75→      setError(null);
 76→
 77→      // Check for duplicate filenames within the batch
 78→      const batchDuplicates = findDuplicateFileNames(files);
 79→      if (batchDuplicates.length > 0) {
 80→        setError({ key: 'duplicateFilesInBatch', params: { names: batchDuplicates.join(', ') } });
 81→        return;
 82→      }
 83→
 84→      // Check for filenames that match already-uploaded table names
 85→      const existingNames = new Set(tables.map((tbl) => tbl.name));
 86→      const alreadyUploaded = files.filter((f) => existingNames.has(f.name)).map((f) => f.name);
 87→      if (alreadyUploaded.length > 0) {
 88→        setError({ key: 'duplicateFilesExist', params: { names: alreadyUploaded.join(', ') } });
 89→        return;
 90→      }
 91→
 92→      let lastName = '';
 93→      try {
 94→        for (const file of files) {
 95→          const formData = new FormData();
 96→          formData.append('file', file);
 97→          const response = await fetch('/api/upload', {
 98→            method: 'POST',
 99→            body: formData,
100→          });
101→          if (!response.ok) {
102→            const errorData = await response.json();
103→            throw new Error(errorData.detail || 'Failed to upload file');
104→          }
105→          const result = await response.json();
106→          // Handle both single table and array of tables (Excel with multiple sheets)
107→          if (Array.isArray(result)) {
108→            lastName = result[result.length - 1]?.name || '';
109→          } else {
110→            lastName = result.name;
111→          }
112→        }
113→        await refreshTables();
114→        if (lastName) {
115→          setEditorQuery(`SELECT * FROM "${lastName}" LIMIT 100`);
116→        }
117→      } catch (e) {
118→        setError(e instanceof Error ? e.message : 'Failed to upload file');
119→      }
120→    },
121→    [refreshTables]
122→  );
123→
124→  const handleQueryExecute = useCallback(
125→    async (sql: string) => {
126→      setError(null);
127→      setQueryResult(null);
128→      try {
